const julyPath = "GPAO-T5/2026-07 정산/7월 정산내역.csv";
const augPath = "GPAO-T5/2026-08 정산/8월 정산내역.csv";

async function readCsv(path) {
  const res = await t5.call("local_file", { action: "read", path });
  const lines = res.result.text.trim().split(/\r?\n/);
  const header = lines[0].split(",");
  const rows = lines.slice(1).map(line => {
    const cols = line.split(",");
    const obj = {};
    header.forEach((h, i) => obj[h] = cols[i]);
    return obj;
  });
  return { header, rows };
}

function parseNumber(v) {
  if (!v) return 0;
  return parseFloat(v.replace(/,/g, "")) || 0;
}

(async () => {
  const july = await readCsv(julyPath);
  const aug = await readCsv(augPath);

  function summarize(data) {
    let totalSales = 0;
    let totalCommission = 0;
    let totalPayout = 0;
    let orderCount = data.rows.length;

    data.rows.forEach(r => {
      totalSales += parseNumber(r["매출액"] || r["총매출"] || r["매출"]);
      totalCommission += parseNumber(r["수수료"] || r["플랫폼수수료"]);
      totalPayout += parseNumber(r["정산금액"] || r["입금액"] || r["지급액"]);
    });

    return { orderCount, totalSales, totalCommission, totalPayout };
  }

  const julySummary = summarize(july);
  const augSummary = summarize(aug);

  function formatSummaryRow(label, j, a) {
    const diff = a - j;
    const diffRate = j === 0 ? "-" : ((diff / j) * 100).toFixed(1) + "%";
    return [label, j.toString(), a.toString(), diff.toString(), diffRate];
  }

  const header = ["항목", "7월", "8월", "증감", "증감률"];
  const rows = [
    formatSummaryRow("주문건수", julySummary.orderCount, augSummary.orderCount),
    formatSummaryRow("총매출", julySummary.totalSales, augSummary.totalSales),
    formatSummaryRow("수수료", julySummary.totalCommission, augSummary.totalCommission),
    formatSummaryRow("정산금액", julySummary.totalPayout, augSummary.totalPayout),
  ];

  // CSV 본문
  const csv = [header.join(","), ...rows.map(r => r.join(","))].join("\n");

  // 요약 설명 텍스트
  function toKRW(n) {
    return n.toLocaleString("ko-KR");
  }

  const lines = [];
  lines.push("2026년 7월 vs 8월 정산 요약");
  lines.push("");
  lines.push(`1) 주문건수: 7월 ${julySummary.orderCount}건 → 8월 ${augSummary.orderCount}건 (" + (augSummary.orderCount - julySummary.orderCount) + "건)" );
  lines.push(`2) 총매출: 7월 ${toKRW(julySummary.totalSales)}원 → 8월 ${toKRW(augSummary.totalSales)}원 (" + toKRW(augSummary.totalSales - julySummary.totalSales) + "원)`);
  lines.push(`3) 수수료: 7월 ${toKRW(julySummary.totalCommission)}원 → 8월 ${toKRW(augSummary.totalCommission)}원 (" + toKRW(augSummary.totalCommission - julySummary.totalCommission) + "원)`);
  lines.push(`4) 정산금액: 7월 ${toKRW(julySummary.totalPayout)}원 → 8월 ${toKRW(augSummary.totalPayout)}원 (" + toKRW(augSummary.totalPayout - julySummary.totalPayout) + "원)`);

  const textSummary = lines.join("\n");

  console.log(JSON.stringify({
    julySummary,
    augSummary,
    csv,
    textSummary
  }));
})();

